import React, { useMemo, useState } from 'react';
import { Note } from '../types';
import { synthesizeTwoConcepts } from '../services/geminiService';
import { Zap, Loader2, X, Info, Target, Network } from 'lucide-react';

interface ConceptMapProps {
  notes: Note[];
}

export const ConceptMap: React.FC<ConceptMapProps> = ({ notes }) => {
  const [selectedNodeIds, setSelectedNodeIds] = useState<string[]>([]);
  const [synthesis, setSynthesis] = useState<string | null>(null);
  const [isSynthesizing, setIsSynthesizing] = useState(false);

  const constellation = useMemo(() => {
    const size = 300;
    const center = { x: 500, y: 350 };

    // Pentagonal Anchor Points
    const vertices = [
      { id: 'M', x: center.x, y: center.y - size },
      { id: 'E', x: center.x + size * Math.cos(-Math.PI/10), y: center.y - size * Math.sin(-Math.PI/10) },
      { id: 'L', x: center.x + size * Math.cos(Math.PI/2 - 4*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 4*Math.PI/5) },
      { id: 'D', x: center.x + size * Math.cos(Math.PI/2 - 6*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 6*Math.PI/5) },
      { id: 'N', x: center.x + size * Math.cos(Math.PI/2 - 8*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 8*Math.PI/5) },
    ];

    const nodes = notes.map((note, idx) => {
      let x = center.x;
      let y = center.y;
      const w = note.weights;
      // Safety check for weights
      const safeW = w || { M: 0, E: 0, L: 0, D: 0, N: 0 };
      const total = (safeW.M + safeW.E + safeW.L + safeW.D + safeW.N) || 1;

      // Weight-based positioning
      x = (center.x * 2 + vertices[0].x * safeW.M + vertices[1].x * safeW.E + vertices[2].x * safeW.L + vertices[3].x * safeW.D + vertices[4].x * safeW.N) / (total + 2);
      y = (center.y * 2 + vertices[0].y * safeW.M + vertices[1].y * safeW.E + vertices[2].y * safeW.L + vertices[3].y * safeW.D + vertices[4].y * safeW.N) / (total + 2);

      // Recursive offset
      x += (Math.sin(idx * 1.5) * 50);
      y += (Math.cos(idx * 2.1) * 50);

      return { ...note, x, y };
    });

    const edges: { source: any, target: any }[] = [];
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        // Safe tag access
        const tagsA = nodes[i].tags || [];
        const tagsB = nodes[j].tags || [];
        const sharedTags = tagsA.filter(tag => tagsB.includes(tag));
        if (sharedTags.length > 0) {
          edges.push({ source: nodes[i], target: nodes[j] });
        }
      }
    }

    return { vertices, nodes, edges };
  }, [notes]);

  const handleNodeClick = (id: string) => {
    setSelectedNodeIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length >= 2) return [prev[1], id];
      return [...prev, id];
    });
  };

  const handleSynthesize = async () => {
    if (selectedNodeIds.length !== 2) return;
    const noteA = notes.find(n => n.id === selectedNodeIds[0]);
    const noteB = notes.find(n => n.id === selectedNodeIds[1]);
    if (!noteA || !noteB) return;

    setIsSynthesizing(true);
    setSynthesis(null);
    try {
      const result = await synthesizeTwoConcepts(noteA, noteB);
      setSynthesis(result);
    } catch (e) {
      setSynthesis("SYNERGY_COLLAPSE: Critical entropic noise detected during synthesis.");
    } finally {
      setIsSynthesizing(false);
    }
  };

  return (
    <div className="h-full bg-[#000000] flex flex-col relative overflow-hidden">
      {/* Nebula Backdrop */}
      <div className="absolute inset-0 opacity-40 pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-[600px] h-[600px] bg-neon-cyan/10 blur-[150px] rounded-full"></div>
        <div className="absolute bottom-1/4 right-1/4 w-[500px] h-[500px] bg-neon-purple/10 blur-[150px] rounded-full"></div>
      </div>

      <div className="p-12 flex justify-between items-start z-10 relative">
        <div>
          <h2 className="text-4xl font-bold text-white font-mono tracking-tighter uppercase mb-2">Spreading_Nodes</h2>
          <p className="text-void-500 font-mono text-[10px] uppercase tracking-[0.5em]">Topology_Sync_v2.0 // Neural_Lattice</p>
        </div>

        <div className="flex space-x-4 items-center">
          {selectedNodeIds.length === 2 && (
            <button 
              onClick={handleSynthesize}
              disabled={isSynthesizing}
              className="group flex items-center space-x-3 bg-white text-black px-8 py-3 rounded-full font-mono text-[10px] uppercase tracking-widest shadow-[0_0_20px_rgba(255,255,255,0.4)] hover:bg-neon-cyan hover:text-white transition-all active:scale-95 animate-pulse"
            >
              {isSynthesizing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Network className="w-4 h-4" />}
              <span>Initiate_Synthesis</span>
            </button>
          )}
          <div className="glass px-6 py-3 rounded-2xl flex space-x-6 text-[9px] font-mono text-void-400 uppercase tracking-[0.2em] border border-white/5 shadow-2xl">
            <span className="flex items-center"><div className="w-1.5 h-1.5 rounded-full bg-neon-cyan mr-2 shadow-[0_0_8px_#22d3ee]"></div> MEANING</span>
            <span className="flex items-center"><div className="w-1.5 h-1.5 rounded-full bg-neon-purple mr-2 shadow-[0_0_8px_#a855f7]"></div> ETHICS</span>
            <span className="flex items-center"><div className="w-1.5 h-1.5 rounded-full bg-neon-teal mr-2 shadow-[0_0_8px_#2dd4bf]"></div> VOID</span>
          </div>
        </div>
      </div>

      <div className="flex-1 relative">
        <svg viewBox="0 0 1000 700" className="w-full h-full">
           <defs>
              <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="6" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
              <linearGradient id="linkGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#22d3ee" stopOpacity="0.4" />
                <stop offset="100%" stopColor="#a855f7" stopOpacity="0.4" />
              </linearGradient>
           </defs>

           {/* Connection Lines (Lattice) */}
           {constellation.edges.map((edge, i) => (
             <line 
               key={`edge-${i}`}
               x1={edge.source.x} y1={edge.source.y}
               x2={edge.target.x} y2={edge.target.y}
               stroke="url(#linkGradient)"
               strokeWidth="1.5"
               strokeDasharray="4 4"
               className="opacity-30 group-hover:opacity-60 transition-opacity"
             />
           ))}

           {/* Synthesis Visual Beam */}
           {selectedNodeIds.length === 2 && (
             <line 
                x1={constellation.nodes.find(n => n.id === selectedNodeIds[0])?.x}
                y1={constellation.nodes.find(n => n.id === selectedNodeIds[0])?.y}
                x2={constellation.nodes.find(n => n.id === selectedNodeIds[1])?.x}
                y2={constellation.nodes.find(n => n.id === selectedNodeIds[1])?.y}
                stroke="#fff"
                strokeWidth="2"
                filter="url(#glow)"
                className="animate-pulse"
             />
           )}

           {/* Conceptual Nodes */}
           {constellation.nodes.map((node) => {
             const isSelected = selectedNodeIds.includes(node.id);
             return (
               <g key={node.id} className="group cursor-pointer" onClick={() => handleNodeClick(node.id)}>
                 {/* Atmosphere */}
                 <circle 
                   cx={node.x} 
                   cy={node.y} 
                   r={20 + node.recursiveDepth * 5} 
                   fill={isSelected ? '#22d3ee' : '#22d3ee'}
                   fillOpacity={isSelected ? 0.3 : 0.03}
                   className="transition-all duration-700 group-hover:fill-opacity-20"
                 />
                 {/* Core Node */}
                 <circle 
                   cx={node.x} 
                   cy={node.y} 
                   r={6 + node.recursiveDepth} 
                   fill={isSelected ? '#fff' : '#22d3ee'}
                   className="transition-all duration-300 shadow-neon-cyan"
                   filter={isSelected ? "url(#glow)" : ""}
                 />
                 {/* Floating Label */}
                 <text 
                   x={node.x} 
                   y={node.y + 35 + node.recursiveDepth * 2} 
                   textAnchor="middle" 
                   fill={isSelected ? '#fff' : '#52525b'} 
                   fontSize="10"
                   fontWeight="600"
                   fontFamily="monospace"
                   className={`transition-all tracking-widest uppercase pointer-events-none ${isSelected ? 'opacity-100 translate-y-0' : 'opacity-0 group-hover:opacity-100 translate-y-[-5px]'}`}
                 >
                   {node.title}
                 </text>
               </g>
             );
           })}
        </svg>
      </div>

      {/* Synthesis Modal Overlay */}
      {synthesis && (
        <div className="absolute inset-0 bg-black/90 backdrop-blur-[40px] flex items-center justify-center p-12 z-[100] animate-in fade-in zoom-in duration-500">
          <div className="max-w-4xl w-full glass-card rounded-[48px] p-16 shadow-[0_0_100px_rgba(168,85,247,0.1)] relative border border-white/10 overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-neon-cyan to-transparent"></div>

            <button onClick={() => setSynthesis(null)} className="absolute top-10 right-10 text-void-500 hover:text-white transition-colors p-2 hover:bg-white/5 rounded-full">
              <X className="w-8 h-8" />
            </button>

            <div className="flex items-center space-x-8 mb-12">
              <div className="w-20 h-20 bg-neon-cyan rounded-[24px] flex items-center justify-center shadow-[0_0_30px_rgba(34,211,238,0.3)]">
                <Target className="w-10 h-10 text-black" />
              </div>
              <div>
                <h3 className="text-3xl font-bold font-mono tracking-tighter text-white uppercase">Conceptual_Synthesis</h3>
                <p className="text-[11px] text-neon-cyan font-mono tracking-[0.4em] uppercase">Axiomatic_Resonance_Confirmed</p>
              </div>
            </div>

            <div className="prose prose-invert max-w-none">
               <p className="text-2xl leading-[1.6] text-void-100 font-serif italic border-l-4 border-neon-cyan/40 pl-10 py-2">
                 {synthesis}
               </p>
            </div>

            <div className="mt-16 pt-10 border-t border-white/5 flex justify-between items-center text-[11px] font-mono text-void-600 uppercase tracking-[0.3em]">
              <span className="flex items-center"><Info className="w-4 h-4 mr-3 text-neon-cyan" /> SIGNAL_STRENGTH: 0.998</span>
              <span className="px-4 py-1 rounded-full bg-neon-cyan/10 text-neon-cyan border border-neon-cyan/20">STABLE_GENESIS</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Source, WeeklyDigest } from '../types';
import { generateWeeklyDigest } from '../services/geminiService';
import { Calendar, RefreshCcw, ArrowRight, Activity, Zap } from 'lucide-react';

interface DigestViewProps {
  sources: Source[];
}

export const DigestView: React.FC<DigestViewProps> = ({ sources }) => {
  const [digest, setDigest] = useState<WeeklyDigest | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchDigest = async () => {
    if (sources.length === 0) return;
    setLoading(true);
    try {
      const result = await generateWeeklyDigest(sources);
      setDigest({
        id: crypto.randomUUID(),
        startDate: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
        endDate: new Date().toISOString(),
        ...result
      });
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (sources.length > 0 && !digest) fetchDigest();
  }, [sources]);

  return (
    <div className="space-y-8 bg-void-950 p-8 h-full overflow-y-auto">
      <div className="flex justify-between items-end mb-8">
        <div>
          <h1 className="text-3xl font-bold font-mono text-void-100 tracking-tighter uppercase">Weekly_Digest</h1>
          <p className="text-void-500 font-mono text-xs uppercase tracking-widest mt-1">SYMBIONT_REPORTS v0.1</p>
        </div>
        <button 
          onClick={fetchDigest} 
          disabled={loading || sources.length === 0}
          className="flex items-center space-x-2 bg-void-900 border border-void-800 text-void-400 px-4 py-2 rounded-lg text-xs font-mono hover:text-awakening transition-all"
        >
          <RefreshCcw className={`w-3 h-3 ${loading ? 'animate-spin' : ''}`} />
          <span>GENERATE_REPORT</span>
        </button>
      </div>

      {digest ? (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="space-y-8">
            <section className="bg-void-900/50 p-8 rounded-2xl border border-void-800 shadow-xl">
              <div className="flex items-center space-x-3 mb-6">
                <Activity className="w-5 h-5 text-awakening" />
