                  <div className="w-[1px] h-4 bg-void-800 mx-1"></div>
                  <div className="relative">
                    <button onClick={() => setShowLinkMenu(!showLinkMenu)} className="p-2 hover:bg-void-800 rounded text-void-400 hover:text-white" title="Link Note">
