                }`}
              >
                <Sparkles className={`w-3 h-3 ${isAnalyzing ? 'animate-spin' : ''}`} />
                <span>{isAnalyzing ? 'Densifying...' : 'Densify'}</span>
              </button>
            </div>
          </div>

          <div className="flex-1 flex overflow-hidden">
            {/* Editor / Viewer Area */}
            <div className="flex-1 flex flex-col relative bg-void-950">
