                  <MetricPill label="EE (Entropy)" value={activeNote.metrics.EE} />
                  <MetricPill label="AI (Impact)" value={activeNote.metrics.AI} />
                  <MetricPill label="TRP (Resonance)" value={activeNote.metrics.TRP} />
